public boolean validateWrite()
{
    boolean ret;

    ret = super();

    if(this.FromLocation == this.ToLocation)
    {
        ret = checkFailed(strFmt("%1 and %2 cannot be same.", fieldPName(NVTrvWorkerExpenseRequest, FromLocation), fieldPName(NVTrvWorkerExpenseRequest, ToLocation)));
    }

    if(this.FromLocation    != ''
        && this.ToLocation  != '')
    {
        NVTrvWorkerLocationPerDiem locationPerDiem = NVTrvWorkerLocationPerDiem::findPerDiem(this.FromLocation, this.ToLocation);

        if(!locationPerDiem)
            ret = checkFailed(strFmt("%1 and %2 is not valid combination.", this.FromLocation, this.ToLocation));
    }

    if(this.FromDate > this.ToDate)
    {
        ret = checkFailed(strFmt("%1 must greater or equal to %2.", fieldPName(NVTrvWorkerExpenseRequest, ToDate), fieldPName(NVTrvWorkerExpenseRequest, FromDate)));
    }


    return ret;
}

public void initValue()
{
    super();

    this.Worker                 = HcmWorkerLookup::currentWorker();
    this.RequestId              = NVNumberSeqApplicationModuleHRM::getTrvWorkerExpenseRequestId();
    this.RequestCreatedDate     = DateTimeUtil::getSystemDate(DateTimeUtil::getCompanyTimeZone());
}

public HcmWorker getWorker()
{
    return HcmWorker::find(this.Worker);
}

public void updatePerDiem()
{
    NVTrvWorkerLocationPerDiem locationPerDiem = NVTrvWorkerLocationPerDiem::findPerDiem(this.FromLocation, this.ToLocation);

    this.PerDiem                    = locationPerDiem.PerDiem;
    this.CurrencyCode               = locationPerDiem.CurrencyCode;
    this.Purpose                    = locationPerDiem.DefaultPurpose;
    this.HotelPercent               = locationPerDiem.HotelPercent;
    this.OtherAllowancePercent      = locationPerDiem.OtherAllowancePercent;

    this.perDiemModified();
}

public void perDiemModified()
{
    Days    totalDays       = this.totalDays();
    this.TotalValue         = totalDays * this.PerDiem;
    Amount   hotelAllowance = this.hotelAllowance() * totalDays;

    if(this.IncludeLastDayHotel == NoYes::No)
    {
        this.TotalValue     = this.TotalValue - (hotelAllowance/this.totalDays());
    }
}

public Amount hotelAllowance()
{
    return this.PerDiem * (this.HotelPercent / 100);
}

public Amount otherAllowance()
{
    return this.PerDiem * (this.OtherAllowancePercent / 100);
}

display public Amount calHotelAllowance()
{
    Amount hotelAllowancePerDiem    = this.hotelAllowance();;
    Amount totalHotelAllowance      = hotelAllowancePerDiem * this.totalDays();

    if(this.IncludeLastDayHotel == NoYes::No)
        totalHotelAllowance = totalHotelAllowance - hotelAllowancePerDiem;

    return totalHotelAllowance;
}

display public Amount calcOtherAllowance()
{
    return this.otherAllowance() * this.totalDays();
}

public void modifiedField(FieldId _fieldId)
{
    super(_fieldId);

    switch(_fieldId)
    {
        case fieldNum(NVTrvWorkerExpenseRequest, FromLocation):
        case fieldNum(NVTrvWorkerExpenseRequest, ToLocation):
            this.updatePerDiem();
            break;

        case fieldNum(NVTrvWorkerExpenseRequest, PerDiem):
        case fieldNum(NVTrvWorkerExpenseRequest, FromDate):
        case fieldNum(NVTrvWorkerExpenseRequest, ToDate):
        case fieldNum(NVTrvWorkerExpenseRequest, IncludeLastDayHotel):
            this.perDiemModified();
            break;
    }
}

