[SysClientCacheDataMethodAttribute(true)]
display public HcmWorkerName workerName()
{
    return this.getWorker().name();
}

[SysClientCacheDataMethodAttribute(true)]
display public Days totalDays()
{
    if(this.ToDate == dateNull() || this.FromDate == dateNull())
        return 1;

    return this.ToDate - this.FromDate + 1;
}

[SysClientCacheDataMethodAttribute(true)]
display public ExchRate exchangeRateMST()
{
    if(this.CurrencyCode == '') return 0;

    CurrencyExchangeHelper reportingExchangeHelper = CurrencyExchangeHelper::newExchangeDate(Ledger::current(), this.RequestCreatedDate);
    return  reportingExchangeHelper.calculateTransactionToReporting(this.CurrencyCode, 1);
}

[SysClientCacheDataMethodAttribute(true)]
display public AmountMST amountMST()
{
    if(this.CurrencyCode == '') return 0;

    CurrencyExchangeHelper reportingExchangeHelper = CurrencyExchangeHelper::newExchangeDate(Ledger::current(), this.RequestCreatedDate);
    return reportingExchangeHelper.calculateTransactionToReporting(this.CurrencyCode, this.TotalValue);
}

public boolean canSubmitToWorkflow(str _workflowType = '')
{
    boolean ret = super(_workflowType);

    if(this.Status      == NVTrvWorkerExpReqWFStatus::NotSubmitted)
        ret = true;
    else
        ret = false;

    return ret;
}

public boolean canEdit()
{
    boolean ret = false;

    if(this.Status      == NVTrvWorkerExpReqWFStatus::NotSubmitted
        || this.Status  == NVTrvWorkerExpReqWFStatus::ChangeRequest)
        ret = true;

    return ret;
}

public static void  updateWorkflowStatus(RefRecId recId , NVTrvWorkerExpReqWFStatus _status)
{
    NVTrvWorkerExpenseRequest requestTable; 

    ttsbegin;
    select forupdate requestTable where requestTable.RecId == recId;
    requestTable.Status = _status;
    requestTable.update();
    ttscommit;
}

public static NVTrvWorkerExpenseRequest find(
    RefRecId _recId,
    boolean _forUpdate = false)
{
    NVTrvWorkerExpenseRequest request;

    request.selectForUpdate(_forUpdate);
    if (_forUpdate)
    {
        request.selectForUpdate(_forUpdate);
    }

    select firstonly crosscompany request
        where request.RecId == _recId;

    return request;
}

public static NVTrvWorkerExpenseRequest findESSRequest(
    str _essRequestId,
    boolean _forUpdate = false)
{
    NVTrvWorkerExpenseRequest request;

    request.selectForUpdate(_forUpdate);
    if (_forUpdate)
    {
        request.selectForUpdate(_forUpdate);
    }

    select firstonly crosscompany request
        where request.ESSRequestId == _essRequestId;

    return request;
}

public void update()
{
    super();

    this.recordChangeLog();
}

private void recordChangeLog()
{
    if(this.ESSRequestId != "")
    {
        NVHcmESSChangeLog::insertRef(this.TableId, this.RecId);
    }
}

public str getESSRequestStatus()
{
    switch(this.Status)
    {
        case NVTrvWorkerExpReqWFStatus::Submitted:
            return 'Submitted';
        case NVTrvWorkerExpReqWFStatus::Cancelled:
            return 'Cancelled';
        case NVTrvWorkerExpReqWFStatus::Approved:
            return 'Approved';
        case NVTrvWorkerExpReqWFStatus::Rejected:
            return 'Rejected';
        default:
            return null;
    }
    return null;
}

public int getESSPurpose()
{
    return this.Purpose == NVTrvWorkerLocationPurpose::Domestic? 0: 1;
}
